return ['domain'=>'publishpress-authors','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'fi','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 09:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'PublishPress Authors mahdollistaa useiden kirjoittajien ja vierailevien kirjoittajien lisäämisen WordPress-kirjoituksiin','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'Päivitä Pro-versioon','This plugin can be deleted.'=>'Tämä laajennus voidaan poistaa.','Actions provided by PublishPress plugins.'=>'Toiminnot, joita tarjoavat PublishPress-laajennukset.','List Authors'=>'Listaa kirjoittajat','Lists PublishPress Authors. Results never include author email addresses.'=>'Listaa PublishPress-kirjoittajat. Tulokset eivät koskaan sisällä kirjoittajien sähköpostiosoitteita.','Get Author'=>'Hae kirjoittaja','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'Hakee yhden PublishPress-kirjoittajan termi-ID:n perusteella. Vastaus ei koskaan sisällä sähköpostiosoitetta.','Get Post Authors'=>'Hae kirjoituskirjoittajat','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'Hakee järjestetyt PublishPress-kirjoittajat, jotka on liitetty yhteen muokattavaan kirjoitukseen. Vastaus ei koskaan sisällä kirjoittajien sähköpostiosoitteita.','Get Author Fields'=>'Hae kirjoittajakentät','Lists enabled author-profile field definitions without exposing profile values.'=>'Listaa käytettävissä olevat kirjoittajaprofiilikenttä määritelmät ilman profiilinarvojen paljastamista.','Author not found.'=>'Kirjoittajaa ei löytynyt.','Post not found.'=>'Kirjoitusta ei löytynyt.','Authors List'=>'Kirjoittajien lista','Display authors list.'=>'Näytä kirjoittajien lista.','Title'=>'Otsikko','Layout'=>'Asettelu','Display All Authors (including those who have not written any posts)'=>'Näytä kaikki kirjoittajat (mukaan lukien ne, jotka eivät ole kirjoittaneet yhtään kirjoitusta)','Enable author\'s search box'=>'Ota käyttöön kirjoittajan hakukenttä','Limits per page'=>'Rajoitukset per sivu','Authors'=>'Kirjoittajat','Order'=>'Järjestys','Order by'=>'Järjestä mukaan','Grid Columns'=>'Ruudukon sarakkeet','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'Kirjoittajan hakukenttä (Erota useat kentät pilkulla(\',\'))','All Authors'=>'Kaikki kirjoittajat','Guest Authors'=>'Vierailevat kirjoittajat','Users Authors'=>'Käyttäjät kirjoittajat','Ascending'=>'Nouseva','Descending'=>'Laskeva','Name'=>'Nimi','Post Counts'=>'Kirjoitusmäärät','First Name'=>'Etunimi','Last Name'=>'Sukunimi','Showing authors starting with %s'=>'Näyttää kirjoittajat, joiden nimet alkavat kirjaimella %s','Showing all authors'=>'Näytetään kaikki kirjoittajat','No authors found.'=>'Kirjoittajia ei löytynyt.','Loading authors...'=>'Ladataan kirjoittajia...','Unable to load authors.'=>'Kirjoittajia ei voitu ladata.','Default Search'=>'Oletushaku','Search Box'=>'Hakukenttä','Search'=>'Haku','Search authors'=>'Hae kirjoittajia','Search authors by'=>'Hae kirjoittajia mukaan lukien','No recent posts from this author'=>'Tältä kirjoittajalta ei ole uusia julkaisuja','Request status.'=>'Pyyntötilanne.','Security error. Kindly reload this page and try again'=>'Turvavirhe. Lataa tämä sivu uudelleen ja yritä uudelleen','You cannot edit an author profile linked to an administrator account.'=>'Et voi muokata kirjoittajan profiilia, joka on linkitetty järjestelmänvalvojan tiliin.','You do not have permission to edit this author profile because it is linked to a user account you do not have permission 